export const reelMedia = (index) => {
  const reel = reels[index % reels.length];
  return { type: "video", desktop: reel.src, mobile: reel.src, tablet: reel.src,
    posterDesktop: reel.poster, posterMobile: reel.poster, alt: reel.title };
};

export const mediaDimensions = { ...featuredDimensions, ...Object.fromEntries(reels.flatMap((reel) =>
  [[reel.src, [reel.width, reel.height]], [reel.poster, [reel.width, reel.height]]])) };
